import express from 'express';

const DAILY_CLOSING_UI = Buffer.from('', 'base64').toString('utf8');
const previousSend = express.response.send;

express.response.send = function dailyClosingUiPatch(body) {
  try {
    const requestPath = this.req?.path || this.req?.url || '';
    if (typeof body === 'string' && requestPath.startsWith('/app.js')) {
      if (!body.includes('async function loadDailyClosing(')) {
        const marker = 'async function loadCashBook';
        const pos = body.indexOf(marker);
        if (pos !== -1) body = body.slice(0,pos) + DAILY_CLOSING_UI + '\n' + body.slice(pos);
      }

      body = body.replace(
        "if (state.view==='cashclosing') return renderCashBook();",
        "if (state.view==='cashclosing') return renderDailyClosing();"
      );

      body = body.replace(
        "else if (view==='cashbook' || view==='cashclosing') loadCashBook();",
        "else if (view==='cashclosing') loadDailyClosing();\n  else if (view==='cashbook') loadCashBook();"
      );
    }
  } catch (_) {}

  return previousSend.call(this, body);
};
